<?php
if(!defined('BRYXA_API'))exit;
function findTracked(string $token):array{global $db;$hash=hash('sha256',$token);$q=$db->prepare('SELECT o.data FROM orders o JOIN order_access a ON o.id=a.order_id WHERE a.token_hash=?');$q->execute([$hash]);$raw=$q->fetchColumn();if(!$raw&&demoMode()){$q=$db->prepare('SELECT data FROM demo_orders WHERE token_hash=?');$q->execute([$hash]);$raw=$q->fetchColumn();}if(!$raw)fail('Link de acompanhamento inválido.',404);return json_decode($raw,true);}
function customerOrder(array $o):array{unset($o['access_link'],$o['reserved_stock']);return $o;}
if(in_array($action,['track-order','customer-account'])&&$method==='POST'){requestLimit('track-account',50);$b=body();$o=findTracked(textValue($b['token']??'',100));$email=strtolower($o['customer']['email']);$q=$db->prepare('SELECT password,auth_version FROM customer_accounts WHERE email=?');$q->execute([$email]);$account=$q->fetch(PDO::FETCH_ASSOC);$hash=$account['password']??null;$version=(int)($account['auth_version']??0);$logged=($_SESSION['customer_email']??'')===$email&&($_SESSION['customer_auth_version']??0)===$version;if($action==='customer-account'){if(!in_array($o['payment_status'],['approved','approved_simulated']))fail('Aguarde a confirmação do pagamento para criar sua conta.');$password=textValue($b['password']??'',300);if($hash){if(!password_verify($password,$hash))fail('Confira sua senha.',401);}else{if(strlen($password)<12)fail('Use pelo menos 12 caracteres.');$db->prepare('INSERT INTO customer_accounts(email,password) VALUES(?,?)')->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);queueEmail('account_created',$email,['name'=>$o['customer']['name']],$email.':account');}session_regenerate_id(true);$_SESSION['customer_email']=$email;$_SESSION['customer_auth_version']=$version;$logged=true;}if(!$logged)reply(['requires_account'=>true,'has_account'=>(bool)$hash,'email'=>$email,'id'=>$o['id'],'payment_status'=>$o['payment_status'],'status'=>$o['status']]);reply(['requires_account'=>false,'order'=>customerOrder($o)]);}
if($action==='order-status'&&$method==='POST'){auth();$b=body();$status=$b['status']??'';if(!in_array($status,['Recebido','Em produção','Enviado','Em trânsito','Entregue','Concluído','Cancelado']))fail('Status inválido.');$table=str_starts_with((string)($b['id']??''),'TESTE-')?'demo_orders':'orders';$db->beginTransaction();$q=$db->prepare('SELECT data FROM '.$table.' WHERE id=?');$q->execute([$b['id']??'']);$o=json_decode($q->fetchColumn()?:'null',true);if(!$o){$db->rollBack();fail('Pedido não encontrado.',404);}if(!in_array($o['payment_status']??'', ['approved','approved_simulated'])&&$status!=='Cancelado'){$db->rollBack();fail('O pagamento ainda não foi aprovado.');}$rank=['Recebido'=>0,'Em produção'=>1,'Enviado'=>2,'Em trânsito'=>3,'Entregue'=>4,'Concluído'=>4];if(in_array($o['status'],['Entregue','Concluído','Cancelado'])&&$status!==$o['status']){$db->rollBack();fail('Este pedido já foi finalizado.',409);}if(isset($rank[$o['status']],$rank[$status])&&$rank[$status]<$rank[$o['status']]){$db->rollBack();fail('Não é possível voltar a uma etapa anterior.',409);}stageOrder($o,$status);saveOrder($o,$table);$db->commit();reply(['ok'=>true,'notification'=>'Notificação preparada; aguardando plataforma de e-mail.']);}
if($action==='order-shipment'&&$method==='POST'){auth();$b=body();$table=str_starts_with((string)($b['id']??''),'TESTE-')?'demo_orders':'orders';$q=$db->prepare('SELECT data FROM '.$table.' WHERE id=?');$q->execute([$b['id']??'']);$o=json_decode($q->fetchColumn()?:'null',true);if(!$o)fail('Pedido não encontrado.',404);foreach(['carrier','tracking_code','shipping_label_id'] as $f)$o[$f]=textValue($b[$f]??'',150);if($o['shipping_label_id']&&!preg_match('/^[a-f0-9-]{36}$/i',$o['shipping_label_id']))fail('Informe o UUID da etiqueta do Melhor Envio.');saveOrder($o,$table);reply(['ok'=>true]);}
function syncShipment(array $o):array{global $db;$i=loadDoc('integrations');if(empty($o['shipping_label_id'])||empty($i['melhor_envio_token']))return $o;$host=$i['sandbox']?'sandbox.melhorenvio.com.br':'www.melhorenvio.com.br';$id=$o['shipping_label_id'];$ch=curl_init('https://'.$host.'/api/v2/me/orders/'.$id);curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>20,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$i['melhor_envio_token'],'Accept: application/json','User-Agent: BRYXA ('.$i['support_email'].')']]);$raw=curl_exec($ch);$code=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($code!==200)fail('Não foi possível atualizar o rastreio.',502);$data=json_decode($raw,true);$db->beginTransaction();$fresh=$db->prepare('SELECT data FROM orders WHERE id=?');$fresh->execute([$o['id']]);$o=json_decode($fresh->fetchColumn(),true);$o['carrier_status']=$data['status']??'unknown';$o['carrier_synced_at']=date('c');if(!empty($data['tracking']))$o['tracking_code']=$data['tracking'];$mapped=['posted'=>'Enviado','delivered'=>'Entregue'];if(isset($mapped[$o['carrier_status']])&&!in_array($o['status'],['Entregue','Concluído','Cancelado'])&&!(($mapped[$o['carrier_status']]==='Enviado')&&$o['status']==='Em trânsito'))stageOrder($o,$mapped[$o['carrier_status']],'Melhor Envio');saveOrder($o);$db->commit();return $o;}
if($action==='order-sync'&&$method==='POST'){auth();$id=textValue(body()['id']??'',100);$q=$db->prepare('SELECT data FROM orders WHERE id=?');$q->execute([$id]);$o=json_decode($q->fetchColumn()?:'null',true);if(!$o)fail('Pedido real não encontrado.',404);if(empty($o['shipping_label_id']))fail('Cadastre a etiqueta do Melhor Envio antes de sincronizar.');reply(['order'=>syncShipment($o)]);}
if($action==='internal-shipment-sync'&&PHP_SAPI==='cli'){$updated=0;foreach($db->query('SELECT data FROM orders')->fetchAll(PDO::FETCH_COLUMN) as $raw){$o=json_decode($raw,true);if(!empty($o['shipping_label_id'])&&!in_array($o['status'],['Entregue','Concluído','Cancelado'])){syncShipment($o);$updated++;}}reply(['updated'=>$updated]);}
